sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isTemplate) {
        return;
    }

    // '2' = Emergency, '1' = Not required
    if (newValue === '2') {
        // If loading an existing Emergency record or changing to Emergency, ensure it's Not required
        g_form.setValue('approval_state', '1');
        g_form.setReadOnly('approval_state', true);
    } else {
        // For Planned ('1'), Transfer ('3'), or empty, re-enable editing
        g_form.setReadOnly('approval_state', false);
    }
}
